    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    out = [row[:] for row in grid]
    labels = [[-1] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if labels[r][c] != -1:
                continue
            color = grid[r][c]
            idx = len(components)
            stack = [(r, c)]
            labels[r][c] = idx
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            labels[ny][nx] == -1 and grid[ny][nx] == color):
                        labels[ny][nx] = idx
                        stack.append((ny, nx))
            components.append((color, cells))

    for idx, (color, cells) in enumerate(components):
        if len(cells) != 1 or color == background:
            continue
        r, c = cells[0]
        adjacent = {}
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dy, c + dx
            if 0 <= nr < h and 0 <= nc < w:
                other = labels[nr][nc]
                other_color = grid[nr][nc]
                if other_color != background:
                    adjacent[other] = adjacent.get(other, 0) + 1

        choices = [(n, components[other][0]) for other, n in adjacent.items() if n >= 2]
        if choices:
            out[r][c] = max(choices)[1]
        else:
            out[r][c] = background

    return out
